using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    //  CalculateTotal – DataRow tests
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero price yields zero total")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity yields zero total")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "Max tax rate (100%)")]
    public void CalculateTotal_ValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal – invalid inputs via DataRow
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1,  0.10, DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    [DataRow(10.00, 1,  -0.1, DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1,  1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DynamicData (method source)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DynamicData(nameof(ApplyDiscount_ValidCases), DynamicDataSourceType.Method,
        DynamicDataDisplayName = nameof(GetApplyDiscountDisplayName))]
    public void ApplyDiscount_ValidInputs_ReturnsDiscountedPrice(
        decimal price, decimal discountPercent, decimal expectedPrice)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expectedPrice, result);
    }

    public static IEnumerable<object[]> ApplyDiscount_ValidCases()
    {
        yield return [100m, 0m,   100m];    // No discount
        yield return [100m, 10m,  90m];     // 10% off
        yield return [100m, 50m,  50m];     // 50% off
        yield return [100m, 100m, 0m];      // 100% off (free)
        yield return [49.99m, 25m, 37.4925m]; // Fractional result
        yield return [0m,    50m, 0m];      // Zero price
    }

    public static string GetApplyDiscountDisplayName(MethodInfo methodInfo, object[] data)
        => $"Price {data[0]:C} with {data[1]}% discount → {data[2]:C}";

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DynamicData (property source)
